INSERT INTO public.cpg_faqs (cpg_id, question, answer, reference_doc, page_number, category, metadata)
VALUES ('CPG-TAVI-SIRIRAJ-2024', 'การพยาบาลผู้ป่วยหลังทำ TAVI ในช่วงวิกฤต 24 ชั่วโมงแรก มีข้อควรระวังสำคัญอย่างไร?', '1. เฝ้าระวัง Hemodynamic stability สังเกต BP, HR, Rhythm ทาง Continuous Monitor
2. ตรวจสอบแผลเจาะตรวจและคลำหา Hematoma บริเวณ Vascular access
3. สังเกตอาการทางระบบประสาท (Neuro signs) เฝ้าระวังภาวะ Embolic stroke
4. ปฏิบัติตามคำสั่งการให้ Antithrombotic therapy อย่างเคร่งครัด', 'คู่มือการพยาบาลผู้ป่วยหลังทำ TAVI ศิริราช (Post TAVR Monitoring)', 'หน้า 1-3', 'TAVI', '{"alert_level":"high","source":"Mock Generator Engine"}'::jsonb);